function normalizeBareTermResultLabel(value) {
  let text = cleanBareTermSearchFocus(value);
  if (!text) return "";
  if (typeof text.normalize === "function") {
    text = text.normalize("NFKC");
  }
  text = text
    .replace(/\s*\([^)]*\)\s*$/gu, "")
    .replace(/\s*（[^）]*）\s*$/gu, "")
    .replace(/\s+[-–—]\s+(?:wikipedia|wiktionary)\s*$/iu, "")
