async function renderPromotedProjectLookup(prompt, language, project) {
  const displayName = projectDisplayName(project, language);
  const repository = projectRepoSlug(project);
  const url = project.url || `https://github.com/${repository}`;
  const description = describeProjectRecord(project, language, "short");
  const providers = WEB_SEARCH_PROVIDERS.map((provider) => provider.id);
  const fusionConstant = webSearchRrfK();
  const body = projectSummaryResponse("project-lookup-promoted", language, {
    "promoted-orgs": PROMOTED_PROJECT_ORGS.join(", "),
    "display-name": displayName,
    "repo-slug": repository,
    "project-url": url,
    description,
    "provider-summary": providers.join(", "),
    "reciprocal-rank-constant": fusionConstant,
  });
  const search = await runWebSearchQuery(displayName, language);
  const evidence = [
    `project:promoted:${repository}`, `source:${url}`,
    "summarization:mode:short", `summarization:language:${language}`,
    `web_search:request:${displayName}`,
    ...providers.map((provider) => `web_search:provider_planned:${provider}`),
    `web_search:fusion_planned:rrf:k=${fusionConstant}`,
    ...(search && Array.isArray(search.evidence) ? search.evidence : []),
  ];
  const grounded = search && search.diagnostics &&
    Array.isArray(search.diagnostics.fused) && search.diagnostics.fused.length > 0;
  return {
    intent: "project_lookup",
    content: grounded ? `${body}\n\n${search.content}` : body,
    confidence: 0.9, evidence,
    ...(search && search.diagnostics ? { diagnostics: search.diagnostics } : {}),
  };
}

async function tryProjectLookup(prompt, language, preferences) {
  // A guide being converted quotes its repository as content; Rust asks installation_conversion first.
  if (tryInstallationConversion(prompt, normalizePrompt(prompt))) return null;
  if (!projectLookupPhaseAdmits(prompt)) return null;
  return tryProjectLookupForPrompt(prompt, prompt, language, preferences);
}

const PROJECT_LOOKUP_EXECUTION_FILE = "method-execution.lino";
const PROJECT_LOOKUP_ATTRIBUTE = "project_lookup";
const PROJECT_LOOKUP_FALLBACK_PHASE = "fallback";
const PROJECT_LOOKUP_IDENTITY_ROUTE = "identity";

// The worker functions of the methods a name lookup is the fallback of
// (`project_lookup fallback` in data/seed/method-execution.lino).
function projectLookupFallbackHandlers() {
  const text = typeof SEED_RAW === "object" ? seedRawText(SEED_RAW, PROJECT_LOOKUP_EXECUTION_FILE) : "";
  const methods = (parseLinoTree(text).children[0]?.children || [])
    .filter((node) => node.children.some((child) =>
      child.name === PROJECT_LOOKUP_ATTRIBUTE && child.value === PROJECT_LOOKUP_FALLBACK_PHASE))
    .map((node) => node.value);
  const bindings = typeof WORKER_HANDLER_REGISTRY === "object" ? WORKER_HANDLER_REGISTRY.workerHandlers : {};
  return methods.map((slug) => self[bindings[slug]]).filter((handler) => typeof handler === "function");
}

// The two phases rust/src/meta_method_dispatch.rs runs project lookup in
// (R1188-U29): an explicit repository reference before the runtime methods,
// unless a fetch or navigation URL claims it (`try_explicit_repository_lookup`);
// a name lookup only as the fallback of the methods above, once their own
// handler declines, and never on the identity route.
function projectLookupPhaseAdmits(prompt) {
  const normalized = normalizePrompt(prompt);
  if (repositoryFromPrompt(prompt)) {
    return extractHttpFetchUrl(prompt, normalized) === null && extractUrlNavigateUrl(prompt, normalized) === null;
  }
  if (solverIntentRoute(prompt) === PROJECT_LOOKUP_IDENTITY_ROUTE) return false;
  return !projectLookupFallbackHandlers().some((handler) => handler(prompt));
}

async function tryProjectLookupForPrompt(prompt, lookupPrompt, language, preferences) {
  if (isTextUrlExtractionPrompt(lookupPrompt)) return null;
  if (githubRepositoryInfoRequest(lookupPrompt, String(lookupPrompt || "").toLowerCase())) {
    return null;
  }
  const promotionEnabled = projectPromotionEnabled(preferences);
  const repo = repositoryFromPrompt(lookupPrompt);
  if (repo) {
    const promoted = promotionEnabled
      ? promotedProjectByRepo(repo.owner, repo.name)
      : null;
    if (promoted) {
      return renderPromotedProjectLookup(prompt, language, promoted);
    }
    return genericProjectLookupAnswer(prompt, language, repo, promotionEnabled);
  }

  const query = extractConceptQuery(lookupPrompt);
  if (!query) return null;
  const project = projectByAlias(query.termOriginal || query.term);
  if (!project) return null;
  if (promotionEnabled && isPromotedProject(project)) {
    return renderPromotedProjectLookup(prompt, language, project);
  }
  return genericProjectLookupAnswer(prompt, language, null, promotionEnabled);
}

// A follow-up fires when the user reports they cannot understand the prior
// answer (seed-grounded detectComprehensionFailure) or when the prompt is a
// terse language-switch request. In the terse case the caller has already
// confirmed a seed-grounded response-language marker is present, so a short
// prompt with no fresh subject of its own is treated as a retarget of the
// previous turn. Mirrors is_language_reanswer_followup in
// src/solver_handlers/response_language_followup.rs — the whole phrase table
// lives in data/seed/meanings-translation.lino, not here (issue #556).
function isLanguageReanswerFollowup(normalized) {
  const text = String(normalized || "").trim().toLowerCase();
  if (!text) return false;
  if (detectComprehensionFailure(text)) return true;
  // CJK markers carry no inter-word spaces, so a bare "用中文" counts as one
  // word here — still terse, still a switch. How short is the
  // terse-word-limit policy of data/seed/handler-rules.lino.
  const wordCount = text.split(/\s+/u).filter(Boolean).length;
  return wordCount <= Number(handlerRulesPolicy("response_language_followup", "terse-word-limit") || 0);
}

// Intents that mean the replay never reached a concrete answer, so the
// retarget is not a useful re-answer and we fall through to the normal
// handlers. Mirrors is_inconclusive in
// src/solver_handlers/response_language_followup.rs.
function isInconclusiveReplayIntent(intent) {
  const value = String(intent || "");
  return (
    value === "unknown" ||
    value === "ill_formed" ||
    value === "punctuation_only_prompt" ||
    value === "concept_lookup_unresolved" ||
    value.startsWith("clarify")
  );
}

// Issue #556: a response-language follow-up ("I do not understand English,
// write in Russian") is not a new question. It replays the previous request
// through the *whole* solver with the requested language forced onto every
// localizable handler, so the retarget covers the entire answerable class —
// not just project lookups. Mirrors try_response_language_followup in
// src/solver_handlers/response_language_followup.rs.
async function tryResponseLanguageFollowup(prompt, normalized, history, preferences) {
  // A directive against a language ("never answer in Russian") is not a request to re-answer in it.
  if (responseLanguageForbidden(prompt)) return null;
  const targetLanguage = detectResponseLanguage(normalized);
  if (!targetLanguage) return null;
  if (!isLanguageReanswerFollowup(normalized)) return null;

  // Recover the most recent user request and the history that preceded it, so
  // the replay sees the same context the original answer did.
  if (!Array.isArray(history)) return null;
  let previousIndex = -1;
  for (let index = history.length - 1; index >= 0; index -= 1) {
    const turn = history[index];
    if (turn && turn.role === "user" && turn.content) {
      previousIndex = index;
      break;
    }
  }
  if (previousIndex < 0) return null;
  const previousUser = String(history[previousIndex].content || "").trim();
  if (!previousUser) return null;
  const priorHistory = history.slice(0, previousIndex);

  // Replay through the whole solver with the requested language forced. The
  // forced language doubles as the recursion guard inside solve().
  const replay = await solve(previousUser, priorHistory, preferences, {}, [], {
    forcedResponseLanguage: targetLanguage,
  });
  if (!replay || isInconclusiveReplayIntent(replay.intent)) return null;

  // Splice the follow-up provenance onto the replayed answer; the answer's own
  // evidence (repository slug, sources, language_to:<code>) already comes from
  // the replay, so these markers only name *why* it was produced.
  const followupEvidence = [
    `response_language_followup:target:${targetLanguage}`,
    `language_to:${targetLanguage}`,
    `response_language_followup:handler:${replay.intent}`,
  ];
  const existing = Array.isArray(replay.evidence) ? replay.evidence : [];
  const merged = existing.slice();
  for (const marker of followupEvidence) {
    if (!merged.includes(marker)) merged.push(marker);
  }
  return { ...replay, evidence: merged };
}

function pickPrimaryProviderId(providers, sourceKind) {
  if (sourceKind === "wikidata") return "wikidata";
  if (sourceKind === "wikipedia") return "wikipedia";
  if (sourceKind === "wiktionary") return "wiktionary";
  if (sourceKind === "internet-archive") return "internet-archive";
  if (Array.isArray(providers) && providers.length > 0) {
    const sorted = providers.slice().sort(
      (a, b) => (WEB_SEARCH_PROVIDER_PRIORITY[a.id] || 999) - (WEB_SEARCH_PROVIDER_PRIORITY[b.id] || 999),
    );
    return sorted[0].id;
  }
  return "";
}

function cleanContextValue(value) {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function evidenceFromUserContext(userContext) {
  if (!userContext || typeof userContext !== "object") return [];
  const evidence = [];
  const fields = [
    ["uiLanguage", "ui_language"],
    ["browserLanguage", "browser_language"],
    ["colorScheme", "color_scheme"],
    ["timeZone", "time_zone"],
    ["locationInference", "location_inference"],
  ];
  for (const [key, label] of fields) {
    const value = cleanContextValue(userContext[key]);
    if (value) evidence.push(`user_context:${label}:${value}`);
  }
  return evidence;
}

function attachUserContext(answer, userContext) {
  if (!answer || typeof answer !== "object") return answer;
  const evidence = evidenceFromUserContext(userContext);
  if (evidence.length === 0) return answer;
  const steps = Array.isArray(answer.steps) ? answer.steps.slice() : [];
  const detail = evidence
    .map((item) => item.replace(/^user_context:/, ""))
    .join(", ");
  steps.push({ step: "user_context", detail });
  return Object.assign({}, answer, {
    evidence: [
      ...(Array.isArray(answer.evidence) ? answer.evidence : []),
      ...evidence,
    ],
    steps: withThinkingLevels(steps),
  });
}

// Issue #153: every prompt should be formalized as a Subject-Verb-Object tuple
// regardless of source language. We emit a deterministic, offline formalization
// here (so the trace is stable even when no APIs are reachable) and, when a
// downstream handler resolves the object to a Wikidata/Wikipedia/Wiktionary
// item, we emit a second `formalize_resolved` step with the real ids. Ids use
// canonical prefixes: `Q<n>` / `P<n>` for Wikidata, `WP:<title>` for
// Wikipedia-only items, `WT:<word>` for Wiktionary-only items, `OP:<verb>` for
// the symbolic operation, and `@USER` for the implicit user subject.
const FORMALIZATION_VERBS = [
  // English
  { verb: "what are the steps to", op: "OP:procedure" },
  { verb: "show me how to", op: "OP:procedure" },
  { verb: "tell me how to", op: "OP:procedure" },
  { verb: "how should i", op: "OP:procedure" },
  { verb: "how could i", op: "OP:procedure" },
  { verb: "how would i", op: "OP:procedure" },
  { verb: "how can i", op: "OP:procedure" },
  { verb: "how do i", op: "OP:procedure" },
  { verb: "how to", op: "OP:procedure" },
  { verb: "search", op: "OP:search" },
  { verb: "find", op: "OP:search" },
  { verb: "lookup", op: "OP:lookup" },
  { verb: "look up", op: "OP:lookup" },
  { verb: "define", op: "OP:define" },
  { verb: "what is", op: "OP:define" },
  { verb: "who is", op: "OP:identify" },
  { verb: "explain", op: "OP:define" },
  { verb: "compute", op: "OP:compute" },
  { verb: "calculate", op: "OP:compute" },
  { verb: "hello", op: "OP:greet" },
  { verb: "hi", op: "OP:greet" },
  { verb: "goodbye", op: "OP:farewell" },
  { verb: "bye", op: "OP:farewell" },
  // Russian
  { verb: "найди", op: "OP:search" },
  { verb: "поищи", op: "OP:search" },
  { verb: "поиск", op: "OP:search" },
  { verb: "что такое", op: "OP:define" },
  { verb: "кто такой", op: "OP:identify" },
  { verb: "объясни", op: "OP:define" },
  { verb: "посчитай", op: "OP:compute" },
  { verb: "вычисли", op: "OP:compute" },
  { verb: "привет", op: "OP:greet" },
  { verb: "здравствуй", op: "OP:greet" },
  { verb: "пока", op: "OP:farewell" },
  { verb: "до свидания", op: "OP:farewell" },
  // Hindi
  { verb: "खोज", op: "OP:search" },
  { verb: "ढूंढ", op: "OP:search" },
  { verb: "क्या है", op: "OP:define" },
  { verb: "कौन है", op: "OP:identify" },
  { verb: "नमस्ते", op: "OP:greet" },
  { verb: "अलविदा", op: "OP:farewell" },
  // Chinese
  { verb: "搜索", op: "OP:search" },
  { verb: "查找", op: "OP:search" },
  { verb: "什么是", op: "OP:define" },
  { verb: "是谁", op: "OP:identify" },
  { verb: "你好", op: "OP:greet" },
  { verb: "再见", op: "OP:farewell" },
];

function exactFormalizationMatch(prompt, normalized) {
  const haystack = String(normalized || "").toLowerCase();
  const raw = String(prompt || "");
  const rawLower = String(prompt || "").toLowerCase();
  for (const { verb, op } of FORMALIZATION_VERBS) {
    if (haystack.startsWith(verb + " ") || haystack === verb) {
      return {
        op,
        verb,
        objectText: haystack === verb ? "" : normalized.slice(verb.length),
        interpretations: [],
      };
    }
    if (rawLower.startsWith(verb + " ") || rawLower === verb) {
      return {
        op,
        verb,
        objectText: rawLower === verb ? "" : raw.slice(verb.length),
        interpretations: [],
      };
    }
    if (haystack.includes(" " + verb + " ")) {
      return { op, verb, objectText: null, interpretations: [] };
    }
  }
  return null;
}

function fuzzyFormalizationMatch(prompt) {
  const matches = FORMALIZATION_VERBS
    .map((entry) => {
      const match = fuzzyPrefixMatch(prompt, entry.verb);
      return match ? Object.assign({ entry }, match) : null;
    })
    .filter(Boolean)
    .sort((left, right) =>
      left.typoCount - right.typoCount || right.end - left.end,
    );
  const best = matches[0];
  if (!best) return null;
  const peers = matches.filter(
    (match) => match.typoCount === best.typoCount && match.end === best.end,
  );
  if (peers.length > 1) {
    return {
      ambiguous: true,
      suggestions: peers.map((match) => match.entry.verb),
      interpretations: [],
    };
  }
  return {
    op: best.entry.op,
    verb: best.entry.verb,
    objectText: String(prompt || "").slice(best.end),
    interpretations: [best.interpretation],
  };
}

function detectFormalizationMatch(prompt, normalized) {
  return exactFormalizationMatch(prompt, normalized) || fuzzyFormalizationMatch(prompt);
}
